import React, { useState, useEffect } from 'react';
import { getAlerts, getAlertStats, getAllTopics } from '../api/api';

// This function makes the time look normal
function formatTime(isoString) {
  if (isoString == null) {
    return 'N/A';
  }
  var myDate = new Date(isoString);
  return myDate.toLocaleString();
}

function AlertsPage() {
  // My states for the data
  const [alerts, setAlerts] = useState([]);
  const [alertStats, setAlertStats] = useState(null);
  const [topics, setTopics] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // My states for the filters
  const [severityFilter, setSeverityFilter] = useState('');
  const [topicFilter, setTopicFilter] = useState('');

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const [pagination, setPagination] = useState(null);

  // This function gets everything from the backend
  async function loadAlerts() {
    setLoading(true);
    setError(null);

    try {
      // Getting alerts
      var alertsData = await getAlerts({
        page: currentPage,
        pageSize: 15,
        severity: severityFilter,
        topic: topicFilter,
      });
      setAlerts(alertsData.data);
      setPagination(alertsData.pagination);

      // Getting topics
      var topicsData = await getAllTopics();
      setTopics(topicsData.topics);

      // Getting stats
      var statsData = await getAlertStats();
      setAlertStats(statsData);

      setLoading(false);
    } catch (err) {
      setError('Could not load alerts. Make sure the backend is running.');
      setLoading(false);
    }
  }

  useEffect(() => {
    loadAlerts();
  }, [currentPage, severityFilter, topicFilter]);

  // Function for when dropdowns change
  function handleFilterChange(e, type) {
    if (type === 'severity') {
      setSeverityFilter(e.target.value);
    }
    if (type === 'topic') {
      setTopicFilter(e.target.value);
    }
    setCurrentPage(1); 
  }

  return (
    <div>
      <div className="page-header">
        <h1>Alerts</h1>
        <p>Sensor threshold violations and system warnings</p>
      </div>

      {alertStats !== null && (
        <div className="stats-grid" style={{ marginBottom: '20px' }}>
          <div className="stat-card">
            <p>Total Alerts</p>
            <h3>{alertStats.total_alerts}</h3>
          </div>
          <div className="stat-card">
            <p>Critical</p>
            <h3 style={{ color: 'red' }}>{alertStats.critical_alerts}</h3>
          </div>
          <div className="stat-card">
            <p>Warnings</p>
            <h3 style={{ color: 'orange' }}>{alertStats.warning_alerts}</h3>
          </div>
        </div>
      )}

      <div className="filters-row">
        <span>Filter by: </span>

        <select value={severityFilter} onChange={(e) => handleFilterChange(e, 'severity')}>
          <option value="">All Severities</option>
          <option value="CRITICAL">Critical Only</option>
          <option value="WARNING">Warning Only</option>
        </select>

        <select value={topicFilter} onChange={(e) => handleFilterChange(e, 'topic')}>
          <option value="">All Devices</option>
          {topics.map((t) => (
            <option key={t} value={t}>{t}</option>
          ))}
        </select>

        <button onClick={loadAlerts}>Refresh</button>
      </div>

      {loading === true ? (
        <p>Loading alerts...</p>
      ) : (
        <div>
          {error !== null && <p>{error}</p>}

          {alerts.length === 0 && <p>No alerts found!</p>}

          {alerts.map((item) => (
            <div key={item.id} className="card" style={{ marginBottom: '10px', border: '1px solid black' }}>
              <p><b>Location:</b> {item.topic}</p>
              <p><b>Time:</b> {formatTime(item.created_at)}</p>
              <p><b>Status:</b> {item.severity}</p>

              <p>Problems:</p>
              {item.violated_keys.map((keyName) => (
                <div key={keyName} style={{ marginLeft: '20px', padding: '5px', backgroundColor: '#eee' }}>
                  <p>Sensor: {keyName}</p>
                  <p>Value: {item.actual_values[keyName]}</p>
                </div>
              ))}
            </div>
          ))}

          {pagination !== null && (
            <div className="pagination">
              <button onClick={() => setCurrentPage(currentPage - 1)} disabled={currentPage === 1}>
                Previous
              </button>
              <span> Page {currentPage} </span>
              <button onClick={() => setCurrentPage(currentPage + 1)} disabled={currentPage === pagination.total_pages}>
                Next
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default AlertsPage;
